const hook = $('Webhook (chat)').first().json;

const history = Array.isArray(hook.history) ? hook.history : [];
const systemContent =
  'You are the PhytoScan Plant Doctor, a helpful and precise botanist assistant. ' +
  'You have a photo of the plant and its last health diagnosis. ' +
  'Answer questions about watering, light, soil, pests, and treatment. Be concise and practical.';

const system = [{ role: 'system', content: systemContent }];

const encoded = $('Encode image').first().json;
const imagePart = encoded && encoded.imageUrl
  ? [{ type: 'image_url', image_url: { url: encoded.imageUrl } }]
  : [];

const userMsg = {
  role: 'user',
  content: [...imagePart, { type: 'text', text: hook.message || '' }]
};

const prior = history.map((m) => ({
  role: m.role === 'assistant' ? 'assistant' : 'user',
  content: String(m.content || '')
}));

return [{
  json: {
    messages: [...system, ...prior, userMsg]
  }
}];

const raw = $input.all()[0].json;
const msg = raw.choices?.[0]?.message ?? {};
const content = Array.isArray(msg.content)
  ? msg.content.map((part) => part.text ?? part.content ?? '').join('')
  : (msg.content || msg.reasoning || '');

if (!String(content).trim()) {
  throw new Error('No reply from model. Raw: ' + JSON.stringify(raw).slice(0, 400));
}
return [{ json: { reply: String(content) } }];

const hook = $('Webhook (chat)').first().json;
const raw =
  typeof hook.imageUrl === 'string' && hook.imageUrl.trim() !== '' ? hook.imageUrl
  : (typeof hook.base64Image === 'string' && hook.base64Image.trim() !== '' ? hook.base64Image
  : '');
const dataUrl = raw.startsWith('data:') ? raw : '';
return [{ json: { ...hook, url: dataUrl ? '' : raw, dataUrl } }];

const resolved = $('Resolve image').first().json;
if (resolved.dataUrl) return [{ json: { imageUrl: resolved.dataUrl } }];

const item = $input.all()[0];
if (item && item.binary && item.binary.data) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buffer && buffer.length > 0) {
    const mime = item.binary.data.mimeType || 'image/jpeg';
    return [{ json: { imageUrl: 'data:' + mime + ';base64,' + buffer.toString('base64') } }];
  }
}

const hook = $('Webhook (chat)').first().json;
throw new Error('No image received. Webhook keys: ' + Object.keys(hook).join(', '));
